1	use biome_analyze::{
2	    Ast, FixKind, Rule, RuleDiagnostic, RuleSource, context::RuleContext, declare_lint_rule,
3	};
4	use biome_console::markup;
5	use biome_diagnostics::Severity;
6	use biome_html_syntax::{AnyHtmlElement, HtmlAttribute, HtmlFileSource};
7	use biome_rowan::{AstNode, BatchMutationExt};
8	use biome_rule_options::no_aria_hidden_on_focusable::NoAriaHiddenOnFocusableOptions;
