13	declare_lint_rule! {
14	    /// Enforce that aria-hidden="true" is not set on focusable elements.
15	    ///
16	    /// `aria-hidden="true"` can be used to hide purely decorative content from screen reader users.
17	    /// A focusable element with `aria-hidden="true"` can be reached by keyboard.
18	    /// This can lead to confusion or unexpected behavior for screen reader users.
19	    ///
20	    /// ## Examples
21	    ///
22	    /// ### Invalid
23	    ///
24	    /// ```html,expect_diagnostic
25	    /// <div aria-hidden="true" tabindex="0"></div>
26	    /// ```
27	    ///
28	    /// ```html,expect_diagnostic
29	    /// <a href="/" aria-hidden="true">link</a>
30	    /// ```
31	    ///
32	    /// ### Valid
33	    ///
34	    /// ```html
35	    /// <div aria-hidden="true"></div>
36	    /// ```
37	    ///
38	    /// ```html
39	    /// <button aria-hidden="true" tabindex="-1"></button>
40	    /// ```
41	    ///
42	    /// ## Resources
43	    ///
44	    /// - [aria-hidden elements do not contain focusable elements](https://dequeuniversity.com/rules/axe/html/4.4/aria-hidden-focus)
45	    /// - [Element with aria-hidden has no content in sequential focus navigation](https://www.w3.org/WAI/standards-guidelines/act/rules/6cfa84/proposed/)
46	    /// - [MDN aria-hidden](https://developer.mozilla.org/en-US/docs/Web/Accessibility/ARIA/Attributes/aria-hidden)
47	    ///
48	    pub NoAriaHiddenOnFocusable {
49	        version: "next",
50	        name: "noAriaHiddenOnFocusable",
51	        language: "html",
52	        sources: &[RuleSource::EslintJsxA11y("no-aria-hidden-on-focusable").same()],
53	        recommended: true,
54	        severity: Severity::Error,
55	        fix_kind: FixKind::Unsafe,
56	    }
57	}
58	
59	pub struct NoAriaHiddenOnFocusableState {
60	    aria_hidden_attribute: HtmlAttribute,
61	}
62	
63	impl Rule for NoAriaHiddenOnFocusable {
64	    type Query = Ast<AnyHtmlElement>;
65	    type State = NoAriaHiddenOnFocusableState;
66	    type Signals = Option<Self::State>;
67	    type Options = NoAriaHiddenOnFocusableOptions;
68	
69	    fn run(ctx: &RuleContext<Self>) -> Self::Signals {
70	        let element = ctx.query();
71	        let aria_hidden_attr = get_truthy_aria_hidden_attribute(element)?;
72	        let file_source = ctx.source_type::<HtmlFileSource>();
73	        let is_html = file_source.is_html();
74	
75	        // Tabindex overrides native focusability: negative removes from tab order,
76	        // non-negative makes the element focusable regardless of element type.
77	        if let Some(tabindex_attr) = element.find_attribute_by_name("tabindex")
78	            && let Some(tabindex_value) = get_tabindex_value(&tabindex_attr)
79	        {
80	            if tabindex_value < 0 {
81	                return None;
82	            }
83	            return Some(NoAriaHiddenOnFocusableState {
84	                aria_hidden_attribute: aria_hidden_attr,
85	            });
86	        }
87	
88	        // Check if element is natively focusable or has contenteditable
89	        if is_focusable_element(element, is_html)? {
90	            return Some(NoAriaHiddenOnFocusableState {
91	                aria_hidden_attribute: aria_hidden_attr,
92	            });
93	        }
94	
95	        None
96	    }
97	
98	    fn diagnostic(ctx: &RuleContext<Self>, _state: &Self::State) -> Option<RuleDiagnostic> {
99	        let node = ctx.query();
100	        Some(
101	            RuleDiagnostic::new(
102	                rule_category!(),
103	                node.syntax().text_trimmed_range(),
104	                markup! {
105	                    "Incorrect use of "<Emphasis>"aria-hidden=\"true\""</Emphasis>" detected."
106	                },
107	            )
108	            .note(markup! {
109	                ""<Emphasis>"aria-hidden"</Emphasis>" should not be set to "<Emphasis>"true"</Emphasis>" on focusable elements because this can lead to confusing behavior for screen reader users."
110	            }),
111	        )
112	    }
113	
114	    fn action(ctx: &RuleContext<Self>, state: &Self::State) -> Option<HtmlRuleAction> {
115	        let mut mutation = ctx.root().begin();
116	        mutation.remove_node(state.aria_hidden_attribute.clone());
117	        Some(HtmlRuleAction::new(
118	            ctx.metadata().action_category(ctx.category(), ctx.group()),
119	            ctx.metadata().applicability(),
120	            markup! { "Remove the "<Emphasis>"aria-hidden"</Emphasis>" attribute from the element." }
121	                .to_owned(),
122	            mutation,
123	        ))
124	    }
125	}
