24	/// Checks if any of the enabled rules is in the project domain and requires the module graph.
25	struct NeedsModuleGraph<'a> {
26	    enabled_rules: Option<&'a [RuleFilter<'a>]>,
27	    needs_module_graph: bool,
28	}
29	
30	impl<'a> NeedsModuleGraph<'a> {
31	    fn new(enabled_rules: Option<&'a [RuleFilter<'a>]>) -> Self {
32	        Self {
33	            enabled_rules,
34	            needs_module_graph: false,
35	        }
36	    }
37	
38	    fn compute(mut self) -> bool {
39	        biome_html_analyze::visit_registry(&mut self);
40	        self.needs_module_graph
41	    }
42	}
