44	impl RegistryVisitor<HtmlLanguage> for NeedsModuleGraph<'_> {
45	    fn record_rule<R>(&mut self)
46	    where
47	        R: Rule<Options: Default, Query: Queryable<Language = HtmlLanguage, Output: Clone>>
48	            + 'static,
49	    {
50	        let filter = RuleFilter::Rule(<R::Group as RuleGroup>::NAME, R::METADATA.name);
51	
52	        if self
53	            .enabled_rules
54	            .is_some_and(|enabled_rules| enabled_rules.contains(&filter))
55	            && R::METADATA.domains.contains(&RuleDomain::Project)
56	        {
57	            self.needs_module_graph = true;
58	        }
59	    }
60	}
